const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const rest = a.slice(at + 1)
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  return colon >= 0
    ? { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
    : { userinfo, host: rest, port: undefined }
}

function removeDots(path) {
  let input = path
  const out = []
  const pop = () => out.pop()
  let res = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../')) { input = input.slice(3); res = res.slice(0, Math.max(0, res.lastIndexOf('/'))) }
    else if (input === '/..') { input = '/'; res = res.slice(0, Math.max(0, res.lastIndexOf('/'))) }
    else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', input[0] === '/' ? 1 : 0)
      const seg = i < 0 ? input : input.slice(0, i)
      res += seg
      input = input.slice(seg.length)
    }
  }
  return res
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

class Fail extends Error {}

function check(parts) {
  const bad = (s) => s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)
  const a = parts.authority !== undefined ? splitAuthority(parts.authority) : {}
  const list = [['path', parts.path], ['userinfo', a.userinfo], ['host', a.host], ['query', parts.query], ['fragment', parts.fragment]]
  for (const [name, v] of list) if (bad(v)) throw new Fail(`the ${name} has a truncated percent-encoding`)
