  const scheme = p.scheme === undefined ? undefined : lower(p.scheme)
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  let path = normPct(p.path)
  if (p.authority !== undefined) {
    const a = splitAuthority(p.authority)
    let port = a.port
    if (port === '' || (port !== undefined && scheme !== undefined && DEFAULT_PORTS[scheme] === port)) port = undefined
    out += '//'
    if (a.userinfo !== undefined) out += normPct(a.userinfo) + '@'
    out += lower(normPct(a.host))
    if (port !== undefined) out += ':' + normPct(port)
  }
