  if (p.authority !== undefined && path === '') path = '/'
  out += path
  if (p.query !== undefined) out += '?' + normPct(p.query)
  if (p.fragment !== undefined) out += '#' + normPct(p.fragment)
  return out
}

function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  if (ref.authority !== undefined) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  if (ref.path === '') {
    return { scheme: base.scheme, authority: base.authority, path: base.path, query: ref.query !== undefined ? ref.query : base.query, fragment: ref.fragment }
  }
  let path = ref.path
  if (!path.startsWith('/')) {
    if (base.authority !== undefined && base.path === '') path = '/' + path
    else {
      const i = base.path.lastIndexOf('/')
      path = i >= 0 ? base.path.slice(0, i + 1) + path : path
    }
  }
  return { scheme: base.scheme, authority: base.authority, path: removeDots(path), query: ref.query, fragment: ref.fragment }
