  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]
  const text = require_stdin()
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      const n = idx + 1
      try {
        let target
        if (mode === 'normalize') target = parse(line)
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
